node_upgrade() {
    needs_help "node_upgrade" "node_upgrade [-y] [--dry-run]" \
        "Upgrade each installed Node.js major to its newest patch and remove the old patches. Alias: nvmc" \
        "${1-}" && return

    local assume_yes=0 dry_run=0 arg
    for arg in "$@"; do
        case "$arg" in
            -y | --yes | --force) assume_yes=1 ;;
            --dry-run) dry_run=1 ;;
